do $$ begin
  if to_regclass('public.administrative_work_items') is null or to_regclass('public.administrative_work_source_links') is null or to_regclass('public.administrative_work_evidence') is null or to_regclass('public.administrative_work_history') is null or to_regclass('public.administrative_work_approvals') is null then raise exception 'durable administrative work tables missing'; end if;
  if not (select relrowsecurity from pg_class where oid='public.administrative_work_items'::regclass) then raise exception 'RLS must be enabled'; end if;
  if has_table_privilege('anon','public.administrative_work_items','SELECT') or has_table_privilege('authenticated','public.administrative_work_items','INSERT') or has_table_privilege('authenticated','public.administrative_work_items','UPDATE') or has_table_privilege('service_role','public.administrative_work_items','DELETE') or has_table_privilege('service_role','public.administrative_work_history','UPDATE') or has_table_privilege('service_role','public.administrative_work_history','DELETE') then raise exception 'unexpected durable work privilege'; end if;
  if not has_table_privilege('service_role','public.administrative_work_items','SELECT,INSERT,UPDATE') or not has_table_privilege('service_role','public.administrative_work_history','SELECT,INSERT') then raise exception 'service role allowlist missing'; end if;
  if has_function_privilege('authenticated','public.execute_administrative_work_r1(text,jsonb,text,text,uuid)','EXECUTE') or not has_function_privilege('service_role','public.execute_administrative_work_r1(text,jsonb,text,text,uuid)','EXECUTE') then raise exception 'R1 RPC boundary invalid'; end if;
  if exists(select 1 from public.administrative_work_items) or exists(select 1 from public.administrative_work_history) then raise exception 'migration must not seed/backfill'; end if;
end $$;
